using Microsoft.Extensions.DependencyInjection;
using System.Collections.Concurrent;using EnterpriseDocumentIntelligence.IndexingService.Application;using EnterpriseDocumentIntelligence.IndexingService.Domain; namespace EnterpriseDocumentIntelligence.IndexingService.Infrastructure; public sealed class InMemoryIndexStore:IIndexStore{private readonly ConcurrentDictionary<string,SearchIndexRecord> _items=new();public Task UpsertAsync(SearchIndexRecord r,CancellationToken ct=default){_items[r.Id]=r;return Task.CompletedTask;}public Task<SearchIndexRecord?> GetAsync(string id,CancellationToken ct=default)=>Task.FromResult(_items.TryGetValue(id,out var r)?r:null);} public static class IndexingServiceInfrastructure{public static IServiceCollection AddIndexingApplication(this IServiceCollection services){services.AddSingleton<IIndexStore,InMemoryIndexStore>();services.AddScoped<IndexingApplication>();return services;}}